<?php $pageTitle='Invigilation';$ready=0;$rooms=0;foreach($sessions as $s){$rooms+=(int)$s['room_count'];if((int)$s['duty_count']>0)$ready++;} ?>
<div class="ops-page invigilation-page ops-enter"><section class="ops-hero"><div><div class="ops-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="45" height="45"><span>Gautam Buddha University<br><b>Examination Cell</b></span></div><p class="ops-kicker">Faculty duty control</p><h1>Invigilation allocation</h1><p>Assign available faculty fairly, prevent session conflicts, and maintain a printable duty chart.</p></div><div class="ops-hero-actions"><a href="<?= e(url('replacements')) ?>"><span class="ops-icon icon-swap" aria-hidden="true"></span>Replacement requests<b aria-hidden="true">→</b></a><span><?= count($sessions) ?> published sessions</span></div></section><?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="invigilation-overview"><div><strong><?= count($sessions) ?></strong><span>Sessions available</span></div><div><strong><?= $ready ?></strong><span>Sessions allocated</span></div><div><strong><?= $rooms ?></strong><span>Rooms requiring duty</span></div><div><strong><?= count($duties) ?></strong><span>Active faculty duties</span></div></section>
<section class="ops-section-head"><div><h2>Allocation queue</h2><p>Generate duties once for each published seating session.</p></div></section><?php if($sessions):?><section class="allocation-queue"><?php foreach($sessions as $i=>$session):$done=(int)$session['duty_count']>0;?><article class="session-allocation <?= $done?'complete':'pending' ?>" style="--ops-order:<?= $i ?>"><div class="session-state"><span class="ops-icon <?= $done?'icon-check':'icon-faculty' ?>" aria-hidden="true"></span></div><div><span><?= e(date('D, d M Y',strtotime($session['exam_date']))) ?></span><h3><?= e($session['cycle_name']) ?></h3><p><?= e($session['shift_name']) ?></p></div><dl><div><dt>Rooms</dt><dd><?= (int)$session['room_count'] ?></dd></div><div><dt>Duties</dt><dd><?= (int)$session['duty_count'] ?></dd></div></dl><form method="post" action="<?= e(url('invigilation/allocate/'.$session['id'])) ?>"><?= csrf_field() ?><button <?= $done?'disabled':'' ?>><span class="ops-icon <?= $done?'icon-check':'icon-spark' ?>" aria-hidden="true"></span><?= $done?'Allocated':'Auto-allocate' ?></button></form></article><?php endforeach;?></section><?php else:?><section class="ops-empty compact"><span class="ops-icon icon-faculty" aria-hidden="true"></span><h2>No sessions ready</h2><p>Publish a seating allocation before assigning invigilators.</p></section><?php endif;?>
<section class="ops-section-head duty-head"><div><h2>Duty chart</h2><p>Current room assignments in examination-date order.</p></div><button class="ops-outline-button" onclick="window.print()"><span class="ops-icon icon-print" aria-hidden="true"></span>Print duty chart</button></section><?php if($duties):?><section class="duty-register"><div class="duty-table-head"><span>Date and shift</span><span>Room</span><span>Faculty member</span><span>Employee ID</span><span>Status</span></div><?php foreach($duties as $i=>$duty):?><article style="--ops-order:<?= $i ?>"><div><strong><?= e(date('d M Y',strtotime($duty['exam_date']))) ?></strong><span><?= e($duty['shift_name']) ?></span></div><b><?= e($duty['room_code']) ?></b><div><strong><?= e($duty['faculty_name']) ?></strong><span><?= e($duty['cycle_name']) ?></span></div><code><?= e($duty['employee_id']) ?></code><span class="ops-status <?= e($duty['duty_status']) ?>"><?= e(ucfirst($duty['duty_status'])) ?></span></article><?php endforeach;?></section><?php else:?><section class="ops-empty compact"><span class="ops-icon icon-clipboard" aria-hidden="true"></span><h2>No duties allocated</h2><p>Use the allocation queue above to build the duty chart.</p></section><?php endif;?></div>
